<div class="result-block" v-if="allMes.fightMes"><div class="result-tips" v-if="allMes.wildMonster?.name&amp;&amp;!allMes.fightMes.result==='win'">捕捉 {{allMes.wildMonster.name}} {{allMes.fightMes.result==="catch"?"成功":"失败"}}!</div><div class="result-tips" v-if="allMes.fightMes.result==='win'"><div class="result-tips" v-for="monster in allMes.fightMes.botMes.monsterList" :key="monster.name">你击败了 {{monster.name}}!</div></div><div class="result-tips" v-if="allMes.fightMes.result==='lose'">你被击败了!</div><div class="result-tip-for" v-for="item in allMes.fightMes.myMes.monsterList" :key="item.name"><div class="result-tips" v-if="item.onGround">{{item.name}} 获得 {{experienceText}} 经验</div></div><div class="result-button" @click="confirm()">确认</div></div>